"""Turns a recording into a standalone Python script that replays it."""

from __future__ import annotations

from .events import Event

HEADER = '''\
# Generated by input-recorder. Replays {count} recorded events.
import time

from pynput.keyboard import Controller as Keyboard, Key
from pynput.mouse import Button, Controller as Mouse

keyboard = Keyboard()
mouse = Mouse()

time.sleep({start_delay})  # time to focus the target window
'''


def _key_expr(key: str) -> str:
    prefix, value = key.split(":", 1)
    if prefix == "char":
        return repr(value)  # repr() quotes and escapes safely
    return f"Key.{value}"


def _line(ev: Event) -> str:
    if ev.kind == "key_down":
        return f"keyboard.press({_key_expr(ev.key)})"
    if ev.kind == "key_up":
        return f"keyboard.release({_key_expr(ev.key)})"
    if ev.kind == "move":
        return f"mouse.position = ({int(ev.x)}, {int(ev.y)})"
    action = "press" if ev.kind == "mouse_down" else "release"
    return f"mouse.position = ({int(ev.x)}, {int(ev.y)})\nmouse.{action}(Button.{ev.button})"


def generate_script(events: list[Event], start_delay: float = 2.0) -> str:
    """Python source that replays ``events`` with their original timing.

    Delays between consecutive events are written as time.sleep() calls;
    gaps shorter than 1 ms are skipped.
    """
    lines = [HEADER.format(count=len(events), start_delay=start_delay)]
    previous_t: float | None = None
    for ev in events:
        if previous_t is not None:
            delay = round(ev.t - previous_t, 4)
            if delay >= 0.001:
                lines.append(f"time.sleep({delay})")
        lines.append(_line(ev))
        previous_t = ev.t
    return "\n".join(lines) + "\n"
